// Code node (Run Once for All Items)
// Busca histórico a partir do nó especificado
const historicoItems = $items("puxaHistorico"); // substitua pelo nome real do nó anterior

// Definições de nomes
const NOME_CLIENTE = "Cliente";
const NOME_AGENTE  = "Carlos";

let historico = "# HISTÓRICO DE CONVERSA\n";

for (const item of historicoItems) {
  const msg = item.json.message;
  if (!msg?.content) continue;

  if (msg.type === "human") {
    historico += `## ${NOME_CLIENTE}: ${msg.content}\n`;
  } else if (msg.type === "ai") {
    historico += `## ${NOME_AGENTE}: ${msg.content}\n`;
  }
}

return [
  {
    json: {
      historico_markdown: historico.trim()
    }
  }
];

/**
 * Code Node - Run Once for All Items
 * Atualiza o contato adicionando um telefone no campo "Phone" (PHONE),
 * inserindo como PRIMEIRO, sem duplicar.
 *
 * ========== CONFIG ==========
 */
const CONTACT_NODE   = "puxaContato";                       // nó onde está o contato existente (json.body ou json)
const TRIGGER_NODE   = "When Executed by Another Workflow";  // nó que traz o telefone (json.telefone)
const FIELD_ID_PHONE = 1836069;                              // field_id do campo "Phone" na sua conta
const ENUM_CODE_NEW  = "WORK";                                // enum_code a usar para o novo número
const ENUM_ID_NEW    = null;                                 // OPCIONAL: defina um enum_id válido; deixe null para não enviar
const DEFAULT_DDI    = "+55";                                // DDI padrão quando o número não vier com '+'
const MOVE_NEW_TO_TOP = true;                                // true = insere no início

/* ===== Helpers ===== */
function normalizePhone(raw) {
  if (raw == null) return null;
  let s = String(raw).trim();
  if (!s) return null;
  if (!s.startsWith('+')) s = DEFAULT_DDI + s.replace(/[^\d]/g, '');
  const keepPlus = s.startsWith('+') ? '+' : '';
  const digits = s.replace(/[^\d]/g, '');
  return digits ? (keepPlus + digits) : null;
}
function samePhone(a, b) {
  const na = String(a || '').replace(/[^\d]/g, '');
  const nb = String(b || '').replace(/[^\d]/g, '');
  return na.length > 0 && na === nb;
}
function getNodeJson(name) {
  try { return $node[name]?.json ?? null; } catch { return null; }
}

/* ===== Lê telefone do nó gatilho ===== */
const triggerJson  = getNodeJson(TRIGGER_NODE);
const telefoneNovo = normalizePhone(triggerJson?.telefone);

// Se não houver telefone novo, devolve os bodies intactos
if (!telefoneNovo) {
  return $input.all().map(it => {
    const fromContactNode = getNodeJson(CONTACT_NODE);
    const bodyFromNode = fromContactNode?.body ?? fromContactNode;
    const bodyFromItem = it.json?.body ?? it.json;
    return { json: (bodyFromNode || bodyFromItem) };
  });
}

const out = [];

for (const it of $input.all()) {
  // Prioriza contato do nó configurado; se não existir, usa o body do item
  const fromContactNode = getNodeJson(CONTACT_NODE);
  const body = (fromContactNode?.body ?? fromContactNode) || it.json?.body || it.json;

  if (!body) {
    out.push({ json: { error: 'Body do contato não encontrado.' } });
    continue;
  }

  if (!Array.isArray(body.custom_fields_values)) {
    body.custom_fields_values = [];
  }

  // Localiza o campo Phone: por field_id, field_code ou field_name
  let phoneField = body.custom_fields_values.find(
    f => f?.field_id === FIELD_ID_PHONE || f?.field_code === "PHONE" || f?.field_name === "Phone"
  );

  // Se não houver, cria com o FIELD_ID_PHONE configurado
  if (!phoneField) {
    phoneField = {
      field_id: FIELD_ID_PHONE,
      field_name: "Phone",
      field_code: "PHONE",
      field_type: "multitext",
      values: []
    };
    body.custom_fields_values.push(phoneField);
  }

  // Garante o array de values
  phoneField.values = Array.isArray(phoneField.values) ? phoneField.values : [];

  // Remove duplicata do mesmo número (normalizado)
  phoneField.values = phoneField.values.filter(v => !samePhone(v?.value, telefoneNovo));

  // === Escolha do enum_id ===
  // 1) Se já existir algum value com o MESMO enum_code e enum_id numérico, reaproveita
  let enumIdToUse = null;
  const existingSameCode = phoneField.values.find(v => String(v?.enum_code).toUpperCase() === String(ENUM_CODE_NEW).toUpperCase() && Number.isInteger(v?.enum_id));
  if (existingSameCode) {
    enumIdToUse = existingSameCode.enum_id;
  } else if (Number.isInteger(ENUM_ID_NEW)) {
    // 2) Caso você tenha configurado manualmente um enum_id válido
    enumIdToUse = ENUM_ID_NEW;
  } else {
    // 3) Caso contrário, não envia enum_id (deixa null) para evitar NotSupportedChoice
    enumIdToUse = null;
  }

  // Monta o novo valor e insere
  const novoValor = {
    value: telefoneNovo,
    enum_id: enumIdToUse,        // pode ser null ou o id que você definiu
    enum_code: ENUM_CODE_NEW
  };

  if (MOVE_NEW_TO_TOP) phoneField.values.unshift(novoValor);
  else                 phoneField.values.push(novoValor);

  out.push({ json: body });
}

return out;

