// Array para armazenar apenas os resultados da validação
const resultados = [];

// Loop sobre os itens de entrada - Validação para números de celular brasileiros
// Formato esperado: +55 + DDD (2 dígitos) + 9 dígitos (começando com 9)
for (const item of $input.all()) {
  try {
    let telefone = item.json.telefone;

    // Verificar se o campo telefone existe
    if (!telefone) {
      resultados.push({
        json: {
          validacao: "Número inválido - Campo telefone não encontrado",
          regiao: null
        }
      });
      continue;
    }

    // Converter para string se não for
    telefone = String(telefone);

    // Remover espaços e caracteres especiais, mantendo apenas números e +
    const telefoneOriginal = telefone;
    telefone = telefone.replace(/[^\d+]/g, '');

    // Verificar se tem o código do país (+55)
    if (!telefone.startsWith('+55')) {
      // Se começar apenas com 55, adicionar o +
      if (telefone.startsWith('55')) {
        telefone = '+' + telefone;
      } else {
        resultados.push({
          json: {
            validacao: "Número inválido - Código do país (+55) não encontrado",
            regiao: null
          }
        });
        continue;
      }
    }

    // Remover o +55 para análise
    const numeroSemPais = telefone.slice(3);

    // Verificar se tem exatamente 11 dígitos (DDD + 9 dígitos do celular)
    if (numeroSemPais.length !== 11) {
      let motivo = numeroSemPais.length < 11 ? 
        `Faltam ${11 - numeroSemPais.length} dígitos` : 
        `Excesso de ${numeroSemPais.length - 11} dígitos`;
      resultados.push({
        json: {
          validacao: `Número inválido - ${motivo}`,
          regiao: null
        }
      });
      continue;
    }

    // Extrair DDD (primeiros 2 dígitos)
    const ddd = parseInt(numeroSemPais.slice(0, 2));

    // Verificar se o DDD é válido
    if (!dddRegioes[ddd]) {
      resultados.push({
        json: {
          validacao: `Número inválido - DDD ${ddd} inexistente`,
          regiao: null
        }
      });
      continue;
    }

    // Extrair o número sem DDD (deve ter exatamente 9 dígitos)
    const numeroSemDDD = numeroSemPais.slice(2);

    // Verificar se tem exatamente 9 dígitos e começa com 9 (celular)
    if (numeroSemDDD.length !== 9) {
      resultados.push({
        json: {
          validacao: `Número inválido - Deve ter exatamente 9 dígitos após o DDD`,
          regiao: null
        }
      });
      continue;
    }

    if (!numeroSemDDD.startsWith('9')) {
      resultados.push({
        json: {
          validacao: "Número inválido - Número deve começar com 9 após o DDD",
          regiao: null
        }
      });
      continue;
    }

    // Se chegou até aqui, o número é válido
    resultados.push({
      json: {
        validacao: `Número válido - ${telefone}`,
        regiao: dddRegioes[ddd],
        telefoneValidado: telefone,
        ddd: ddd
      }
    });

  } catch (error) {
    resultados.push({
      json: {
        validacao: `Número inválido - Erro na validação: ${error.message}`,
        regiao: null
      }
    });
  }
}

return resultados;
